	/* RSEQ-DEVIATION: get_resource_handle hoisted before enable_device —
	 * the single ratified per-OS preamble deviation; BAR sizing with
	 * memory decode off (witness eth_e1000.c:219-224).
	 * [license: backend-zephyr-c-e1000 GRILL D02] */
